package pk.clearpremiumwater;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity {
 private Db db; private LinearLayout root,body; private final int NAVY=Color.rgb(16,36,58),RED=Color.rgb(190,35,45),BG=Color.rgb(246,248,251); private static final int CREATE_BACKUP=11,RESTORE_BACKUP=12;
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);home();}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(8,8,8,8);return t;}
 private Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(RED));b.setOnClickListener(v->r.run());return b;}
 private EditText edit(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setPadding(12,8,12,8);return e;}
 private void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);TextView head=text("CLEAR PREMIUM WATER\n"+title,20,Color.WHITE);head.setTypeface(null,1);head.setBackgroundColor(NAVY);root.addView(head);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setPadding(14,10,14,20);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void home(){base("Billing & Ledger");body.addView(text("Faram Rahimabad, Mingora, Swat  |  03425214489",13,NAVY));body.addView(text("Offline billing • Customer-specific rates • PKR",14,NAVY));long customers=count("customers"),invoices=count("invoices"),products=count("products"),receivable=allOutstanding();body.addView(text("CUSTOMERS  "+customers+"     INVOICES  "+invoices+"     PRODUCTS  "+products,16,NAVY));body.addView(text("TOTAL OUTSTANDING: Rs. "+receivable,20,RED));addButton("＋  New Invoice",this::newInvoice);addButton("Customers & Customer Ledger",this::customers);addButton("Products & Customer Rates",this::rates);addButton("Outstanding Balances",this::outstanding);addButton("Invoice History / PDF",this::invoiceHistory);addButton("Record a Payment",this::payment);addButton("Backup Database",()->backup());addButton("Restore Database",()->restore());}
 private void addButton(String s,Runnable r){body.addView(button(s,r),new LinearLayout.LayoutParams(-1,-2));}
 private long count(String table){try(Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM "+table,null)){return c.moveToFirst()?c.getLong(0):0;}}
 private long allOutstanding(){try(Cursor c=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(invoice_total),0)-(SELECT COALESCE(SUM(amount),0) FROM payments) FROM invoices",null)){return c.moveToFirst()?Math.max(0,c.getLong(0)):0;}}
 private void customers(){base("Customers");addButton("＋ Add Customer",()->customerForm(0,null,"","",""));try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,phone,address FROM customers WHERE active=1 ORDER BY name",null)){while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1),phone=c.getString(2),address=c.getString(3);addButton(name+"  •  Rs. "+db.outstanding(id),()->customerDetail(id));body.addView(text((phone==null?"":phone)+"  |  "+(address==null?"":address),12,NAVY));}}addButton("← Dashboard",this::home);}
 private void customerForm(long id,String unused,String name,String phone,String address){LinearLayout l=new LinearLayout(this);l.setPadding(20,10,20,10);l.setOrientation(1);EditText n=edit("Customer name *"),p=edit("Phone number"),a=edit("Address");n.setText(name);p.setText(phone);a.setText(address);l.addView(n);l.addView(p);l.addView(a);new AlertDialog.Builder(this).setTitle(id==0?"Add customer":"Edit customer").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{if(n.getText().toString().trim().isEmpty()){toast("Customer name is required");return;}if(id==0)db.addCustomer(n.getText().toString(),p.getText().toString(),a.getText().toString());else db.updateCustomer(id,n.getText().toString(),p.getText().toString(),a.getText().toString());customers();}).show();}
 private void customerDetail(long id){String name="Customer";try(Cursor c=db.getReadableDatabase().rawQuery("SELECT name FROM customers WHERE id=?",new String[]{""+id})){if(c.moveToFirst())name=c.getString(0);}final String customerName=name;base(name+" • Ledger");body.addView(text("Outstanding balance: Rs. "+db.outstanding(id),20,RED));addButton("Edit Customer",()->{try(Cursor c=db.getReadableDatabase().rawQuery("SELECT name,phone,address FROM customers WHERE id=?",new String[]{""+id})){if(c.moveToFirst())customerForm(id,null,c.getString(0),c.getString(1),c.getString(2));}});addButton("Set Product Rates",()->customerRates(id));addButton("Record Payment",()->paymentFor(id));try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,invoice_date,invoice_total,previous_balance FROM invoices WHERE customer_id=? ORDER BY id DESC",new String[]{""+id})){while(c.moveToNext()){long iid=c.getLong(0);addButton("Invoice CPW-"+String.format(Locale.US,"%05d",iid)+" • "+c.getString(1)+" • Rs. "+c.getLong(2),()->sharePdf(iid));body.addView(text("Previous balance at invoice: Rs. "+c.getLong(3),12,NAVY));}}body.addView(text("PAYMENT HISTORY",16,RED));try(Cursor c=db.getReadableDatabase().rawQuery("SELECT paid_date,amount,note FROM payments WHERE customer_id=? ORDER BY id DESC",new String[]{""+id})){while(c.moveToNext())body.addView(text(c.getString(0)+"  •  Rs. "+c.getLong(1)+"  •  "+c.getString(2),13,NAVY));}addButton("← Customers",this::customers);}
 private static class Item {long id;String name;Item(long i,String n){id=i;name=n;}public String toString(){return name;}}
 private ArrayList<Item> getCustomers(){ArrayList<Item>a=new ArrayList<>();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM customers WHERE active=1 ORDER BY name",null)){while(c.moveToNext())a.add(new Item(c.getLong(0),c.getString(1)));}return a;}
 private ArrayList<Item> getProducts(){ArrayList<Item>a=new ArrayList<>();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM products WHERE active=1 ORDER BY id",null)){while(c.moveToNext())a.add(new Item(c.getLong(0),c.getString(1)));}return a;}
 private void rates(){base("Products & Rates");EditText product=edit("New product name");body.addView(product);addButton("Add Product",()->{if(product.getText().toString().trim().isEmpty()){toast("Enter a product name");return;}db.addProduct(product.getText().toString());rates();});for(Item p:getProducts())body.addView(text(p.name,15,NAVY));body.addView(text("Choose a customer to edit their individual product rates:",14,NAVY));for(Item c:getCustomers())addButton(c.name+" • edit rates",()->customerRates(c.id));addButton("← Dashboard",this::home);}
 private void customerRates(long customer){String cname="Customer";try(Cursor c=db.getReadableDatabase().rawQuery("SELECT name FROM customers WHERE id=?",new String[]{""+customer})){if(c.moveToFirst())cname=c.getString(0);}base("Rates: "+cname);for(Item p:getProducts()){LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(text(p.name,14,NAVY),new LinearLayout.LayoutParams(0,-2,1));EditText rate=edit("Rate Rs.");long saved=db.rate(customer,p.id);if(saved>0)rate.setText(""+saved);row.addView(rate,new LinearLayout.LayoutParams(110,-2));body.addView(row);rate.setTag(p.id);rate.setOnFocusChangeListener((v,focus)->{if(!focus)saveRate(customer,p.id,rate);});rate.setOnEditorActionListener((v,a,e)->{saveRate(customer,p.id,rate);return false;});}addButton("Save All Rates",()->{for(int i=0;i<body.getChildCount();i++){View v=body.getChildAt(i);if(v instanceof LinearLayout){LinearLayout row=(LinearLayout)v;for(int j=0;j<row.getChildCount();j++)if(row.getChildAt(j) instanceof EditText){EditText e=(EditText)row.getChildAt(j);Object tag=e.getTag();if(tag instanceof Long)saveRate(customer,(Long)tag,e);}}}toast("Rates saved");customerDetail(customer);});addButton("← Back",()->customerDetail(customer));}
 private void saveRate(long customer,long product,EditText e){try{String s=e.getText().toString().trim();if(!s.isEmpty())db.setRate(customer,product,productIdRate(s));}catch(Exception ex){toast("Enter a valid non-negative whole-rupee rate");}}
 private long productIdRate(String s){long n=Long.parseLong(s);if(n<0)throw new IllegalArgumentException();return n;}
 private void newInvoice(){ArrayList<Item> cs=getCustomers(),ps=getProducts();if(cs.isEmpty()||ps.isEmpty()){toast("Add a customer and product first");return;}base("New Invoice");Spinner cust=new Spinner(this);cust.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cs));body.addView(text("Customer",14,NAVY));body.addView(cust);TextView prev=text("Previous outstanding: Rs. 0",16,RED);body.addView(prev);cust.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){prev.setText("Previous outstanding: Rs. "+db.outstanding(cs.get(pos).id));}});
  class Row{Spinner prod;EditText qty,rate;Row(Spinner p,EditText q,EditText r){prod=p;qty=q;rate=r;}}ArrayList<Row> rows=new ArrayList<>();LinearLayout lines=new LinearLayout(this);lines.setOrientation(1);body.addView(lines);Runnable addRow=()->{LinearLayout row=new LinearLayout(this);row.setOrientation(1);Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ps));EditText qty=edit("Quantity"),rate=edit("Rate Rs.");qty.setInputType(2);rate.setInputType(2);row.addView(sp);LinearLayout sub=new LinearLayout(this);sub.addView(qty,new LinearLayout.LayoutParams(0,-2,1));sub.addView(rate,new LinearLayout.LayoutParams(0,-2,1));row.addView(sub);lines.addView(row);Row r=new Row(sp,qty,rate);rows.add(r);Runnable load=()->{Item c=cs.get(cust.getSelectedItemPosition());Item p=ps.get(sp.getSelectedItemPosition());long val=db.rate(c.id,p.id);rate.setText(val==0?"":""+val);};sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){load.run();}});cust.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){prev.setText("Previous outstanding: Rs. "+db.outstanding(cs.get(pos).id));load.run();}});};addRow.run();addButton("＋ Add Product Line",addRow);EditText paid=edit("Payment received now (Rs.)");paid.setInputType(2);body.addView(paid);EditText date=edit("Invoice date (YYYY-MM-DD)");date.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));body.addView(date);EditText note=edit("Note (optional)");body.addView(note);
  addButton("Save Invoice & Create PDF",()->{try{Item c=cs.get(cust.getSelectedItemPosition());ArrayList<Db.InvoiceLine> data=new ArrayList<>();for(Row r:rows){Item p=ps.get(r.prod.getSelectedItemPosition());String q=r.qty.getText().toString().trim(),rt=r.rate.getText().toString().trim();if(q.isEmpty()&&rt.isEmpty())continue;if(q.isEmpty()||rt.isEmpty())throw new IllegalArgumentException("Fill quantity and rate for each used product");long quantity=Long.parseLong(q),price=Long.parseLong(rt);if(quantity<=0||price<0)throw new IllegalArgumentException("Quantity must be positive and rate non-negative");data.add(new Db.InvoiceLine(p.id,p.name,quantity,price));db.setRate(c.id,p.id,price);}long payment=paid.getText().toString().trim().isEmpty()?0:Long.parseLong(paid.getText().toString().trim());long iid=db.createInvoice(c.id,date.getText().toString().trim(),data,payment,note.getText().toString());File pdf=InvoicePdf.create(this,db,iid);shareFile(pdf,"Invoice created. Share or save the PDF.");}catch(Exception e){toast("Could not save invoice: "+e.getMessage());}});addButton("← Dashboard",this::home);}
 private void invoiceHistory(){base("Invoice History");try(Cursor c=db.getReadableDatabase().rawQuery("SELECT i.id,i.invoice_date,i.invoice_total,cu.name FROM invoices i JOIN customers cu ON cu.id=i.customer_id ORDER BY i.id DESC",null)){while(c.moveToNext()){long id=c.getLong(0);addButton("CPW-"+String.format(Locale.US,"%05d",id)+" • "+c.getString(1)+" • Rs. "+c.getLong(2),()->sharePdf(id));body.addView(text(c.getString(3),12,NAVY));}}addButton("← Dashboard",this::home);}
 private void outstanding(){base("Outstanding Balances");for(Item c:getCustomers()){long b=db.outstanding(c.id);if(b>0)addButton(c.name+" • Rs. "+b,()->customerDetail(c.id));}addButton("← Dashboard",this::home);}
 private void payment(){ArrayList<Item> cs=getCustomers();if(cs.isEmpty()){toast("Add a customer first");return;}base("Record Payment");Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cs));body.addView(sp);EditText amount=edit("Amount received (Rs.)");amount.setInputType(2);body.addView(amount);EditText date=edit("Date YYYY-MM-DD");date.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));body.addView(date);EditText note=edit("Payment method / note");body.addView(note);addButton("Save Payment",()->{try{Item c=cs.get(sp.getSelectedItemPosition());long n=Long.parseLong(amount.getText().toString());db.addPayment(c.id,null,date.getText().toString(),n,note.getText().toString());toast("Payment recorded");customerDetail(c.id);}catch(Exception e){toast("Payment not saved: "+e.getMessage());}});addButton("← Dashboard",this::home);}
 private void paymentFor(long customer){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText amount=edit("Amount received (Rs.)"),date=edit("Date YYYY-MM-DD"),note=edit("Payment note");amount.setInputType(2);date.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));l.addView(amount);l.addView(date);l.addView(note);new AlertDialog.Builder(this).setTitle("Record payment").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{db.addPayment(customer,null,date.getText().toString(),Long.parseLong(amount.getText().toString()),note.getText().toString());customerDetail(customer);}catch(Exception e){toast("Payment not saved: "+e.getMessage());}}).show();}
 private void sharePdf(long id){try{shareFile(InvoicePdf.create(this,db,id),"Share invoice PDF");}catch(Exception e){toast("PDF error: "+e.getMessage());}}
 private void shareFile(File f,String title){try{Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".provider",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,uri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,title));}catch(Exception e){Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,Uri.fromFile(f));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(i,title));}catch(Exception ex){toast("PDF saved in app cache: "+f.getAbsolutePath());}}}
 private void backup(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"clear_premium_water_backup.db");startActivityForResult(i,CREATE_BACKUP);}
 private void restore(){new AlertDialog.Builder(this).setTitle("Restore database").setMessage("Restore replaces all current app records. Create a backup first. Continue?").setNegativeButton("Cancel",null).setPositiveButton("Choose backup",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,RESTORE_BACKUP);}).show();}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(req==CREATE_BACKUP){db.close();try(InputStream in=new FileInputStream(getDatabasePath(Db.NAME));OutputStream out=getContentResolver().openOutputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b);}db=new Db(this);toast("Backup saved");}else if(req==RESTORE_BACKUP){db.close();try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(getDatabasePath(Db.NAME))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b);}db=new Db(this);db.getReadableDatabase();toast("Backup restored");home();}}catch(Exception e){db=new Db(this);toast("Backup operation failed: "+e.getMessage());}}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
